"use client";
// @zeus-internal
import { Aperture, Box, Circle, Command, Gem, Hexagon, type LucideIcon, Octagon, Triangle } from "lucide-react";
import { motion, useAnimationFrame, useMotionValue, useReducedMotion } from "motion/react";
import { useEffect, useRef } from "react";
type Logo = {
    name: string;
