const SPEED = 26;
const VIEW_INSET = 0.1;
export default function LogoCloudMarquee() {
    const x = useMotionValue(0);
    const sectionRef = useRef<HTMLElement>(null);
    const trackRef = useRef<HTMLDivElement>(null);
    const hoveredRef = useRef(false);
    const visibleRef = useRef(false);
    const reduceMotion = useReducedMotion();
    useEffect(() => {
        const section = sectionRef.current;
        if (!section)
            return;
        const observer = new IntersectionObserver((entries) => {
            for (const entry of entries)
                visibleRef.current = entry.isIntersecting;
        }, { rootMargin: `-${VIEW_INSET * 100}% 0px -${VIEW_INSET * 100}% 0px` });
        observer.observe(section);
        return () => observer.disconnect();
    }, []);
    useAnimationFrame((_, delta) => {
        const track = trackRef.current;
        if (!track || reduceMotion || !visibleRef.current || hoveredRef.current)
            return;
        const half = track.offsetWidth / 2;
        if (half <= 0)
            return;
        let next = x.get() - (SPEED * delta) / 1000;
        if (next <= -half)
            next += half;
        x.set(next);
    });
    return (<div className="art:w-full">
      <section ref={sectionRef} className="art:w-full art:px-4 art:py-16 art:@min-[640px]/artemis:px-8">
        <div className="art:mx-auto art:w-full art:max-w-6xl">
