          <div className="art:relative art:mt-8 art:overflow-hidden art:[mask-image:linear-gradient(to_right,transparent,black_10%,black_90%,transparent)]" onMouseEnter={() => {
            hoveredRef.current = true;
        }} onMouseLeave={() => {
            hoveredRef.current = false;
        }}>
            <div className="art:flex art:w-max">
              <motion.div ref={trackRef} className="art:flex art:w-max art:items-center art:gap-12 art:pr-12" style={{ x }}>
                {TRACK.map((logo, index) => {
            const Icon = logo.icon;
            return (<span key={index} className="art:flex art:shrink-0 art:items-center art:gap-2 art:text-muted-foreground/70 art:transition-colors art:hover:text-foreground">
                      <Icon className="art:size-5" strokeWidth={1.75}/>
                      <span className="art:font-semibold art:text-lg art:tracking-tight">{logo.name}</span>
                    </span>);
        })}
              </motion.div>
            </div>
          </div>
        </div>
      </section>
    </div>);
}

