    const [step, setStep] = useState(0);
    const running = inView && pageVisible;
    useEffect(() => {
        if (!running)
            return;
        const id = window.setInterval(() => setStep((s) => s + 1), STEP_MS);
        return () => window.clearInterval(id);
    }, [running]);
    const template = { gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))` };
    const slots = Array.from({ length: columns }, (_, i) => i);
    return (<div aria-hidden="true" className="art:relative art:flex art:h-28 art:items-center art:border art:border-border">
      <div className="art:pointer-events-none art:absolute art:inset-0 art:grid" style={template}>
        {slots.map((i) => (<span key={i} className="art:border-border art:border-r art:last:border-r-0"/>))}
      </div>
      <div ref={ref} className="art:grid art:relative art:z-10 art:w-full" data-slot="logos-carousel" style={template}>
        {slots.map((i) => {
            const brand = BRANDS[(step * columns + i) % BRANDS.length];
            const transition = { duration: DURATION, ease: EASE_OUT_QUAD, delay: i * COLUMN_STAGGER };
            return (<div key={i} className="art:relative art:overflow-hidden" data-slot="logos-carousel-column">
              <div aria-hidden="true" className="art:pointer-events-none art:invisible art:select-none">
                <BrandMark brand={BRANDS[i]}/>
              </div>
              <AnimatePresence initial={false}>
                <motion.div key={brand.name} className="art:absolute art:inset-0 art:flex art:items-center art:justify-center" data-slot="logos-carousel-logo" initial={{ opacity: 0, y: "60%" }} animate={{ opacity: 1, y: "0%" }} exit={{ opacity: 0, y: "-60%" }} transition={transition}>
                  <BrandMark brand={brand}/>
                </motion.div>
              </AnimatePresence>
            </div>);
        })}
      </div>
    </div>);
}

